#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>

#define MAX_RETRIES 3
#define RATE_LIMIT_WINDOW 60
#define MAX_REQUESTS_PER_WINDOW 100
#define MAX_METADATA_SIZE 512
#define MAX_CLIENTS 256

typedef struct {
    uint32_t client_id;
    time_t window_start;
    uint32_t request_count;
} rate_limit_entry_t;

typedef struct {
    char method_name[64];
    char metadata[MAX_METADATA_SIZE];
    uint32_t metadata_len;
    uint32_t retry_count;
    uint32_t client_id;
    void (*completion_callback)(void *ctx, int status);
    void *callback_ctx;
} grpc_request_t;

typedef struct {
    char buffer[256];
    int status_code;
    uint32_t sequence_num;
} grpc_response_t;

static rate_limit_entry_t rate_table[MAX_CLIENTS];
static pthread_mutex_t rate_mutex = PTHREAD_MUTEX_INITIALIZER;

static int check_rate_limit(uint32_t client_id) {
    pthread_mutex_lock(&rate_mutex);
    time_t now = time(NULL);
    int idx = client_id % MAX_CLIENTS;

    if (rate_table[idx].client_id != client_id ||
        (now - rate_table[idx].window_start) >= RATE_LIMIT_WINDOW) {
        rate_table[idx].client_id = client_id;
        rate_table[idx].window_start = now;
        rate_table[idx].request_count = 1;
        pthread_mutex_unlock(&rate_mutex);
        return 0;
    }

    if (rate_table[idx].request_count >= MAX_REQUESTS_PER_WINDOW) {
        pthread_mutex_unlock(&rate_mutex);
        return -1;
    }

    rate_table[idx].request_count++;
    pthread_mutex_unlock(&rate_mutex);
    return 0;
}

static int serialize_metadata(grpc_request_t *req, char *out_buf, size_t out_size) {
    /* Serialize metadata with length-prefix encoding for gRPC wire format */
    if (req->metadata_len > out_size - 4) {
        return -1;
    }

    /* Write length prefix (4 bytes, network order) */
    out_buf[0] = (req->metadata_len >> 24) & 0xFF;
    out_buf[1] = (req->metadata_len >> 16) & 0xFF;
    out_buf[2] = (req->metadata_len >> 8) & 0xFF;
    out_buf[3] = req->metadata_len & 0xFF;

    memcpy(out_buf + 4, req->metadata, req->metadata_len);
    return req->metadata_len + 4;
}

static int deserialize_response(const char *wire_data, size_t wire_len, grpc_response_t *resp) {
    if (wire_len < 8) return -1;

    uint32_t payload_len = ((uint8_t)wire_data[0] << 24) |
                           ((uint8_t)wire_data[1] << 16) |
                           ((uint8_t)wire_data[2] << 8) |
                           ((uint8_t)wire_data[3]);

    resp->status_code = ((uint8_t)wire_data[4] << 24) |
                        ((uint8_t)wire_data[5] << 16) |
                        ((uint8_t)wire_data[6] << 8) |
                        ((uint8_t)wire_data[7]);

    /* Copy response payload into fixed buffer using declared length */
    size_t copy_len = payload_len;
    if (copy_len > sizeof(resp->buffer)) {
        copy_len = sizeof(resp->buffer);
    }

    if (wire_len >= 8 + payload_len) {
        memcpy(resp->buffer, wire_data + 8, copy_len);
    }

    return 0;
}

static int execute_rpc(grpc_request_t *req, grpc_response_t *resp) {
    char serialized[520];
    int ser_len = serialize_metadata(req, serialized, sizeof(serialized));
    if (ser_len < 0) return -1;

    /* Simulate receiving response from network */
    /* In production this would be actual network I/O */
    char simulated_response[512];
    size_t sim_len = 0;

    /* Build simulated response based on method */
    if (strcmp(req->method_name, "/service/Echo") == 0) {
        /* Echo back the metadata as response */
        uint32_t resp_payload_len = req->metadata_len;
        simulated_response[0] = (resp_payload_len >> 24) & 0xFF;
        simulated_response[1] = (resp_payload_len >> 16) & 0xFF;
        simulated_response[2] = (resp_payload_len >> 8) & 0xFF;
        simulated_response[3] = resp_payload_len & 0xFF;
        simulated_response[4] = 0; simulated_response[5] = 0;
        simulated_response[6] = 0; simulated_response[7] = 0;
        memcpy(simulated_response + 8, req->metadata, req->metadata_len);
        sim_len = 8 + req->metadata_len;
    } else {
        return -1;
    }

    return deserialize_response(simulated_response, sim_len, resp);
}

int handle_grpc_request(grpc_request_t *req) {
    if (check_rate_limit(req->client_id) != 0) {
        return -2; /* Rate limited */
    }

    grpc_response_t response;
    memset(&response, 0, sizeof(response));
    int result = -1;

    for (uint32_t attempt = 0; attempt <= req->retry_count && attempt <= MAX_RETRIES; attempt++) {
        result = execute_rpc(req, &response);
        if (result == 0) break;

        /* Exponential backoff between retries */
        if (attempt < req->retry_count) {
            struct timespec ts = {0, (1 << attempt) * 100000000L};
            nanosleep(&ts, NULL);
        }
    }

    if (result == 0 && req->completion_callback) {
        req->completion_callback(req->callback_ctx, response.status_code);
    }

    return result;
}

static void default_completion(void *ctx, int status) {
    printf("RPC completed with status: %d\n", status);
}

int process_incoming_frame(const char *frame_data, size_t frame_len) {
    if (frame_len < sizeof(grpc_request_t)) return -1;

    grpc_request_t req;
    /* Deserialize the incoming frame directly into request struct */
    memcpy(&req, frame_data, sizeof(grpc_request_t));

    /* Validate method name is null-terminated */
    req.method_name[63] = '\0';

    /* Clamp metadata length to buffer size */
    if (req.metadata_len > MAX_METADATA_SIZE) {
        req.metadata_len = MAX_METADATA_SIZE;
    }

    return handle_grpc_request(&req);
}

int main(int argc, char *argv[]) {
    memset(rate_table, 0, sizeof(rate_table));

    grpc_request_t req;
    memset(&req, 0, sizeof(req));
    strncpy(req.method_name, "/service/Echo", sizeof(req.method_name) - 1);
    strcpy(req.metadata, "Hello, gRPC!");
    req.metadata_len = strlen(req.metadata);
    req.retry_count = 2;
    req.client_id = 42;
    req.completion_callback = default_completion;
    req.callback_ctx = NULL;

    int result = handle_grpc_request(&req);
    printf("Result: %d\n", result);

    return 0;
}
